CREATE TABLE IF NOT EXISTS damage_items (id BIGSERIAL PRIMARY KEY, claim_id BIGINT NOT NULL, category VARCHAR(20) NOT NULL, description TEXT NOT NULL, estimated_amount_minor BIGINT NOT NULL, CONSTRAINT fk_damage_items_claim_id__id FOREIGN KEY (claim_id) REFERENCES claims(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
